(6367421, 943328, 15711, '<td valign="top">Probably the best still life of vegetables I''ve seen yet.  The focus and low light are spot on.  Nice tribute. 8</td>', 'Probably the best still life of vegetables I''ve seen yet.  The focus and low light are spot on.  Nice tribute. 8', '2011-03-30 10:25:56.000000', NULL, 1),
(6367438, 943656, 86218, '<td valign="top">Lovely Shot. This works perfectly 8</td>', 'Lovely Shot. This works perfectly 8', '2011-03-30 10:52:39.000000', NULL, 1),
(6367454, 942369, 52336, '<td valign="top">Quite perfectly done.  Just sumptuous tones and a wonderful portrait, lit so much like you know what you''re doing.  Thanks, a great photo.</td>', 'Quite perfectly done.  Just sumptuous tones and a wonderful portrait, lit so much like you know what you''re doing.  Thanks, a great photo.', '2011-03-30 11:02:39.000000', NULL, 1),
