(6367809, 943365, 16148, '<td valign="top">You nailed the lighting and exposure of an Edward Weston image.  Congratulations on this achievement no matter what score you receive.  Thanks</td>', 'You nailed the lighting and exposure of an Edward Weston image.  Congratulations on this achievement no matter what score you receive.  Thanks', '2011-03-30 14:00:28.000000', NULL, 1),
(6367821, 943101, 10785, '<td valign="top">Excellent Weston Like Portrait! Good pose representative of his headshots, very contemplative. Use of digital medium really lacks the depth that Weston''s film portraits show but here it may also be the distance of the background to the model, as Weston shot many outdoor portraits. (My last comment is not to say your photo is lacking in any way, just different because of the medium chosen.)<br/> <br/>Overall an excellent example!</td>', 'Excellent Weston Like Portrait! Good pose representative of his headshots, very contemplative. Use of digital medium really lacks the depth that Weston''s film portraits show but here it may also be the distance of the background to the model, as Weston shot many outdoor portraits. (My last comment is not to say your photo is lacking in any way, just different because of the medium chosen.) Overall an excellent example!', '2011-03-30 14:10:31.000000', NULL, 1),
(6367822, 942369, 124255, '<td valign="top">Great shot, not so much "Weston" like though (I don''t care for his people shots myself) anyway that''s all that kept the score at 6 for me<br/> <br/>good luck</td>', 'Great shot, not so much "Weston" like though (I don''t care for his people shots myself) anyway that''s all that kept the score at 6 for me good luck', '2011-03-30 14:11:44.000000', NULL, 1),
(6367853, 942648, 98022, '<td valign="top">Great detail.</td>', 'Great detail.', '2011-03-30 14:52:23.000000', NULL, 1),
(6367854, 942748, 98022, '<td valign="top">Nice textures.</td>', 'Nice textures.', '2011-03-30 14:53:34.000000', NULL, 1),
(6367867, 943591, 112972, '<td valign="top">Very nice tones.  Beautifully done.  The old textures are awesome in this.  This one showed up first on my voting list.</td>', 'Very nice tones.  Beautifully done.  The old textures are awesome in this.  This one showed up first on my voting list.', '2011-03-30 15:16:20.000000', NULL, 1),
(6367868, 942597, 112972, '<td valign="top">Very unique portrait.  Very well done!</td>', 'Very unique portrait.  Very well done!', '2011-03-30 15:20:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6367873, 943260, 124256, '<td valign="top">I definitely feel the Weston vibe with this shot and I like it a lot.  I keep on wanting to specify what I think it lacks to fully echo Weston, but I find that each thing I think of is actually there when I look closer.  So I think what is lacking is subtle.  I suggesting making your shot more obviously a Weston homage.  Not sure how to do that.  Very nice shot.</td>', 'I definitely feel the Weston vibe with this shot and I like it a lot.  I keep on wanting to specify what I think it lacks to fully echo Weston, but I find that each thing I think of is actually there when I look closer.  So I think what is lacking is subtle.  I suggesting making your shot more obviously a Weston homage.  Not sure how to do that.  Very nice shot.', '2011-03-30 15:25:22.000000', NULL, 1),
(6367878, 942820, 112972, '<td valign="top">This is wonderful!  One of the best in challenge.  I am giving this a 9.</td>', 'This is wonderful!  One of the best in challenge.  I am giving this a 9.', '2011-03-30 15:30:39.000000', NULL, 1),
(6367881, 943328, 112972, '<td valign="top">Excellent lighting!  I expect this to finish high.</td>', 'Excellent lighting!  I expect this to finish high.', '2011-03-30 15:34:07.000000', NULL, 1),
(6367885, 943182, 124256, '<td valign="top">Nice shot.  Based on my interpretation of Weston, I think your shot needs more contrast (whiter whites) and is too grainy.</td>', 'Nice shot.  Based on my interpretation of Weston, I think your shot needs more contrast (whiter whites) and is too grainy.', '2011-03-30 15:34:59.000000', NULL, 1),
(6367887, 943228, 124256, '<td valign="top">Hmm, I struggle to confidently tie this to Weston''s style.  I think the biggest problem is that everything is not in focus.  I think he would have removed the seaweed from this piece of driftwood as well to highlight its form and lines.</td>', 'Hmm, I struggle to confidently tie this to Weston''s style.  I think the biggest problem is that everything is not in focus.  I think he would have removed the seaweed from this piece of driftwood as well to highlight its form and lines.', '2011-03-30 15:37:00.000000', NULL, 1),
(6367888, 942718, 124256, '<td valign="top">Nice shot.  The feeling I get is that Weston would have a more pristine, perfect specimen (a problem I ran into with this challenge myself).</td>', 'Nice shot.  The feeling I get is that Weston would have a more pristine, perfect specimen (a problem I ran into with this challenge myself).', '2011-03-30 15:38:38.000000', NULL, 1),
(6367891, 942559, 124256, '<td valign="top">Based on my limited exposure to Weston I think I can see the connection and think it''s successful.  For me part of what makes this work is the dark band on the left that looks like it could be a crevice with darkness behind; an ambiguity caused by reducing the sense of depth.</td>', 'Based on my limited exposure to Weston I think I can see the connection and think it''s successful.  For me part of what makes this work is the dark band on the left that looks like it could be a crevice with darkness behind; an ambiguity caused by reducing the sense of depth.', '2011-03-30 15:41:25.000000', NULL, 1),
(6367893, 943413, 124256, '<td valign="top">I want to write this entry off, but the intersecting shadows keep bringing me back.  I can''t say I see the Weston in the shot, but I''m certainly not an expert.  The shadows saved you from a low score from me.</td>', 'I want to write this entry off, but the intersecting shadows keep bringing me back.  I can''t say I see the Weston in the shot, but I''m certainly not an expert.  The shadows saved you from a low score from me.', '2011-03-30 15:43:33.000000', NULL, 1),
(6367895, 943604, 124256, '<td valign="top">Nice.  I love the rich blacks, and although not everything is sharply in focus, I think enough is for it to echo Weston''s style.  What''s missing in my opinion is enough balance between the lights and the darks.  Plus the pinpoints of light reflecting off the shell really detract and the Westonness.</td>', 'Nice.  I love the rich blacks, and although not everything is sharply in focus, I think enough is for it to echo Weston''s style.  What''s missing in my opinion is enough balance between the lights and the darks.  Plus the pinpoints of light reflecting off the shell really detract and the Westonness.', '2011-03-30 15:45:28.000000', NULL, 1),
(6367899, 943139, 124256, '<td valign="top">Very nice.  I think Weston would have had deeper blacks.</td>', 'Very nice.  I think Weston would have had deeper blacks.', '2011-03-30 15:48:09.000000', NULL, 1),
(6367901, 943584, 124256, '<td valign="top">I haven''t seen Weston shoot a subject quite like this.  I think he would though, and I think he would have shot it about like this.  Well done!</td>', 'I haven''t seen Weston shoot a subject quite like this.  I think he would though, and I think he would have shot it about like this.  Well done!', '2011-03-30 15:50:11.000000', NULL, 1),
(6367905, 942704, 16106, '<td valign="top">The framing seems very cramped to me with the barn and the field shoved down and pressurized. A bit more room for the eye to roam would have given the frame a bit more quiet.</td>', 'The framing seems very cramped to me with the barn and the field shoved down and pressurized. A bit more room for the eye to roam would have given the frame a bit more quiet.', '2011-03-30 15:54:16.000000', NULL, 1),
(6367908, 943472, 124256, '<td valign="top">Nice subject.  I am only somewhat convinced Weston would have chosen this subject and shot it like this.  I definitely think he would have put the whole thing in focus, though.</td>', 'Nice subject.  I am only somewhat convinced Weston would have chosen this subject and shot it like this.  I definitely think he would have put the whole thing in focus, though.', '2011-03-30 15:55:15.000000', NULL, 1),
(6367910, 943627, 16106, '<td valign="top">Yup this is the goods, lovely tones with a frame full of textures, and it has the quiet that i expect in a Weston, full marks</td>', 'Yup this is the goods, lovely tones with a frame full of textures, and it has the quiet that i expect in a Weston, full marks', '2011-03-30 15:56:02.000000', NULL, 1),
(6367913, 942597, 124256, '<td valign="top">Wow, what a striking image!  I think you captured the range and balance from black to white in a way that makes me think of Weston.  Personally I think this is better than a Weston portrait.  So, you lose points for too good of a shot.</td>', 'Wow, what a striking image!  I think you captured the range and balance from black to white in a way that makes me think of Weston.  Personally I think this is better than a Weston portrait.  So, you lose points for too good of a shot.', '2011-03-30 15:57:00.000000', NULL, 1),
(6367917, 943618, 124256, '<td valign="top">This almost works for me to echo Weston.  I feel that maybe it would help if the shot was more tightly cropped, but I''m not sure.</td>', 'This almost works for me to echo Weston.  I feel that maybe it would help if the shot was more tightly cropped, but I''m not sure.', '2011-03-30 15:58:10.000000', NULL, 1),
(6367921, 943488, 124256, '<td valign="top">Maybe I haven''t seen enough Weston, but I really think he would have the subject (or at least something) in focus.  I do think you nailed the range of darks and lights, though.  I also don''t think Weston said as much about his subjects as you did with this shot.</td>', 'Maybe I haven''t seen enough Weston, but I really think he would have the subject (or at least something) in focus.  I do think you nailed the range of darks and lights, though.  I also don''t think Weston said as much about his subjects as you did with this shot.', '2011-03-30 15:59:37.000000', NULL, 1),
(6367922, 942660, 124256, '<td valign="top">I don''t recall seeing a Weston photo like this.  That said I think this is one of the more successful unique Westony captures.  I just wish the leg of the right came out sharper and more striking.</td>', 'I don''t recall seeing a Weston photo like this.  That said I think this is one of the more successful unique Westony captures.  I just wish the leg of the right came out sharper and more striking.', '2011-03-30 16:01:26.000000', NULL, 1),
(6367926, 942507, 16106, '<td valign="top">In a classic shot like this focus is so important, and it is sadly missing. the framing and lighting are strong, but without focus there isn''t the textural element that would complete the shot</td>', 'In a classic shot like this focus is so important, and it is sadly missing. the framing and lighting are strong, but without focus there isn''t the textural element that would complete the shot', '2011-03-30 16:02:44.000000', NULL, 1),
(6367928, 942555, 124256, '<td valign="top">I think Weston''s images capture more ambiguous or unexplainable motion and contradictory curves in images that are this dark and cropped this tightly.  I think a much sharper contrast between the black background the and lightest areas of the shell would make a big difference.</td>', 'I think Weston''s images capture more ambiguous or unexplainable motion and contradictory curves in images that are this dark and cropped this tightly.  I think a much sharper contrast between the black background the and lightest areas of the shell would make a big difference.', '2011-03-30 16:07:00.000000', NULL, 1),
(6367929, 943328, 16106, '<td valign="top">A lovely image with great dynamic lighting which creates drama in the highlights and shadows, but in a challenge where we are meant to follow the style of Weston, the image''s best feature becomes a detriment. A more subtle even light is more in Weston''s style, letting textures rise up out of tone. A very nice shot, but not a great response to the challenge.</td>', 'A lovely image with great dynamic lighting which creates drama in the highlights and shadows, but in a challenge where we are meant to follow the style of Weston, the image''s best feature becomes a detriment. A more subtle even light is more in Weston''s style, letting textures rise up out of tone. A very nice shot, but not a great response to the challenge.', '2011-03-30 16:08:02.000000', NULL, 1),
(6367930, 942915, 124256, '<td valign="top">Hmm, I think Weston would approve of this image.  I am just distracted by the out of focus are on the left of the stem.  Not affecting you score I think you have a stray white pixel off on the right.</td>', 'Hmm, I think Weston would approve of this image.  I am just distracted by the out of focus are on the left of the stem.  Not affecting you score I think you have a stray white pixel off on the right.', '2011-03-30 16:08:37.000000', NULL, 1),
(6367933, 942889, 124256, '<td valign="top">Is this inspired by Weston?  Sorry, I don''t see it.  That said, I love the shot, very nice!</td>', 'Is this inspired by Weston?  Sorry, I don''t see it.  That said, I love the shot, very nice!', '2011-03-30 16:09:46.000000', NULL, 1),
(6367934, 943284, 124256, '<td valign="top">My take is that Weston''s portraits aren''t very portrait-y.  Your shot is a beautiful portrait, but I think misses the Weston flavor.</td>', 'My take is that Weston''s portraits aren''t very portrait-y.  Your shot is a beautiful portrait, but I think misses the Weston flavor.', '2011-03-30 16:11:51.000000', NULL, 1),
(6367935, 943477, 124256, '<td valign="top">Mmm, creative take on Weston!  I wish the shapes and contours suggested alternative biology, but still I think this is very well conceived and executed.  Well done!</td>', 'Mmm, creative take on Weston!  I wish the shapes and contours suggested alternative biology, but still I think this is very well conceived and executed.  Well done!', '2011-03-30 16:13:06.000000', NULL, 1),
(6367936, 942722, 124256, '<td valign="top">I don''t understand what I''m looking at, but the tonal profile and suggestive pose implied seem very Westony to me.  I think Weston would have shot it in perfect focus, though.</td>', 'I don''t understand what I''m looking at, but the tonal profile and suggestive pose implied seem very Westony to me.  I think Weston would have shot it in perfect focus, though.', '2011-03-30 16:15:00.000000', NULL, 1),
(6367938, 942968, 124256, '<td valign="top">Hmm, I think I can see what you were going for here, but my opinion is that Weston would have shot something less busy.  I think the trees and vines you selected are very Westony, I just think the twigs are in your way.</td>', 'Hmm, I think I can see what you were going for here, but my opinion is that Weston would have shot something less busy.  I think the trees and vines you selected are very Westony, I just think the twigs are in your way.', '2011-03-30 16:16:51.000000', NULL, 1),
(6367939, 943595, 16106, '<td valign="top">I hate voting on shots like this. Its beautiful. It has nothing to do with the challenge. black and white or free study, full marks. Weston or water bottle...Im not seeing how this fits.<br/> <br/>I do love the technique, the line looks like the neck of a cello, a great capture.</td>', 'I hate voting on shots like this. Its beautiful. It has nothing to do with the challenge. black and white or free study, full marks. Weston or water bottle...Im not seeing how this fits. I do love the technique, the line looks like the neck of a cello, a great capture.', '2011-03-30 16:17:00.000000', NULL, 1),
(6367940, 942976, 124256, '<td valign="top">I think Weston''s shot would have been in perfect focus, and if this is, it seems like it''s not to me.  I don''t know what caused the white "p" dead center, but if I ignore that, I think your lighting is perfect.</td>', 'I think Weston''s shot would have been in perfect focus, and if this is, it seems like it''s not to me.  I don''t know what caused the white "p" dead center, but if I ignore that, I think your lighting is perfect.', '2011-03-30 16:18:18.000000', NULL, 1),
(6367949, 943668, 16106, '<td valign="top">Grrr, the best of the nudes, the lighting and processing is spot on, and you include a four panel hollow core door as a major element? you absolutely nailed that marble like skin tone that Weston got and my eye gets pulled away by raised panels and rumpled terrycloth. Oh for a better background and it would have ribboned.</td>', 'Grrr, the best of the nudes, the lighting and processing is spot on, and you include a four panel hollow core door as a major element? you absolutely nailed that marble like skin tone that Weston got and my eye gets pulled away by raised panels and rumpled terrycloth. Oh for a better background and it would have ribboned.', '2011-03-30 16:22:24.000000', NULL, 1),
(6367950, 942795, 124256, '<td valign="top">Great shot.  As far as echoing Weston, I think it would be even better if the background was starker and darker.  Still, well done!</td>', 'Great shot.  As far as echoing Weston, I think it would be even better if the background was starker and darker.  Still, well done!', '2011-03-30 16:22:48.000000', NULL, 1),
(6367952, 942880, 124256, '<td valign="top">Nice, I see the Westoniness.</td>', 'Nice, I see the Westoniness.', '2011-03-30 16:23:10.000000', NULL, 1),
(6367954, 943180, 124256, '<td valign="top">Hmm, I want to like this one more, but I don''t.  My favorite thing about this shot is the grey area where you see the back of the film.  I don''t like anything about the background, I wish you couldn''t see it, especially the shadow.  I''m not sure why though.  I don''t think Weston would have taken this shot.  I think he would at least like the unusual way it is rolled.</td>', 'Hmm, I want to like this one more, but I don''t.  My favorite thing about this shot is the grey area where you see the back of the film.  I don''t like anything about the background, I wish you couldn''t see it, especially the shadow.  I''m not sure why though.  I don''t think Weston would have taken this shot.  I think he would at least like the unusual way it is rolled.', '2011-03-30 16:25:31.000000', NULL, 1),
(6367955, 942776, 124256, '<td valign="top">I want to like this one more.  For me, the parallel lines on the floor (also reflected on the bowl) really diminish the shot.</td>', 'I want to like this one more.  For me, the parallel lines on the floor (also reflected on the bowl) really diminish the shot.', '2011-03-30 16:26:37.000000', NULL, 1),
(6367957, 943605, 124256, '<td valign="top">Yes, I think this says Weston.  I wish the highlights were whiter, but I like this shot.</td>', 'Yes, I think this says Weston.  I wish the highlights were whiter, but I like this shot.', '2011-03-30 16:28:23.000000', NULL, 1),
(6367958, 943489, 124256, '<td valign="top">I like how the stem is the star instead of the body, but I am pretty sure Weston would have kept everything in focus.  If everything was, though, I think the pepper would look too ordinary.  Still, I really like your idea.</td>', 'I like how the stem is the star instead of the body, but I am pretty sure Weston would have kept everything in focus.  If everything was, though, I think the pepper would look too ordinary.  Still, I really like your idea.', '2011-03-30 16:30:06.000000', NULL, 1),
(6367959, 943625, 124256, '<td valign="top">This shot makes me wince.  I don''t care to comment on that aspect anymore.  The lighting I think is far too harsh for Westonality.  Otherwise nice.</td>', 'This shot makes me wince.  I don''t care to comment on that aspect anymore.  The lighting I think is far too harsh for Westonality.  Otherwise nice.', '2011-03-30 16:31:02.000000', NULL, 1),
(6367961, 942921, 124256, '<td valign="top">I could be wrong, but I don''t think Weston would have used such a starkly white backdrop for the shot.  I almost like the model''s pose.  I just don''t like what the left arm does to the shot.</td>', 'I could be wrong, but I don''t think Weston would have used such a starkly white backdrop for the shot.  I almost like the model''s pose.  I just don''t like what the left arm does to the shot.', '2011-03-30 16:33:08.000000', NULL, 1),
(6367962, 942865, 124256, '<td valign="top">This almost works for me but not quite.  I like your idea.</td>', 'This almost works for me but not quite.  I like your idea.', '2011-03-30 16:34:13.000000', NULL, 1),
(6367966, 942410, 124256, '<td valign="top">I love this shot.  It does echo some Weston aesthetic, but I just don''t feel like the subject is sufficiently Westony.</td>', 'I love this shot.  It does echo some Weston aesthetic, but I just don''t feel like the subject is sufficiently Westony.', '2011-03-30 16:40:13.000000', NULL, 1),
(6367969, 943666, 124256, '<td valign="top">Yeah, I can see the Westonness here.  Somehow the model seems more awkward in this position than Weston''s models seemed though.</td>', 'Yeah, I can see the Westonness here.  Somehow the model seems more awkward in this position than Weston''s models seemed though.', '2011-03-30 16:41:30.000000', NULL, 1),
(6367970, 942748, 96751, '<td valign="top">I like the angle, and the lighting is really delicate - almost too delicate for Weston.  (not voting)</td>', 'I like the angle, and the lighting is really delicate - almost too delicate for Weston.  (not voting)', '2011-03-30 16:42:43.000000', NULL, 1),
(6367972, 943668, 96751, '<td valign="top">Although the nude itself is nice, I find the towel and door distracting.  (not voting)</td>', 'Although the nude itself is nice, I find the towel and door distracting.  (not voting)', '2011-03-30 16:43:14.000000', NULL, 1),
(6367973, 942498, 124256, '<td valign="top">Nice.  Something I miss from Weston''s originals is the in focus inside of the shell.  I think something that makes his nautilus shots great is the shell''s milkiness inside sharply in focus.</td>', 'Nice.  Something I miss from Weston''s originals is the in focus inside of the shell.  I think something that makes his nautilus shots great is the shell''s milkiness inside sharply in focus.', '2011-03-30 16:43:26.000000', NULL, 1),
(6367974, 943221, 96751, '<td valign="top">Though this is a nice door, there is a slight tilt to the left which I find distracting.  Also, the lighting seems just a bit flat to my eye.  (not voting)</td>', 'Though this is a nice door, there is a slight tilt to the left which I find distracting.  Also, the lighting seems just a bit flat to my eye.  (not voting)', '2011-03-30 16:44:12.000000', NULL, 1),
(6367975, 943635, 124256, '<td valign="top">Nice homage.  I think the left leg and foot are in too awkward a position.</td>', 'Nice homage.  I think the left leg and foot are in too awkward a position.', '2011-03-30 16:44:23.000000', NULL, 1),
(6367976, 942326, 96751, '<td valign="top">Seems a bit too abstract to be a Weston.  (not voting)</td>', 'Seems a bit too abstract to be a Weston.  (not voting)', '2011-03-30 16:44:32.000000', NULL, 1),
(6367978, 942820, 124256, '<td valign="top">Hmm, I really like this one.  Definitely echoes what I think Weston would do.  Well done.</td>', 'Hmm, I really like this one.  Definitely echoes what I think Weston would do.  Well done.', '2011-03-30 16:44:58.000000', NULL, 1),
(6367979, 943625, 96751, '<td valign="top">A bit too contrasty, but the "erotic" vegetable is definitely Weston.  (not voting)</td>', 'A bit too contrasty, but the "erotic" vegetable is definitely Weston.  (not voting)', '2011-03-30 16:45:18.000000', NULL, 1),
(6367980, 943471, 96751, '<td valign="top">Nice shapes, although I find it is lacking in detail and tonal richness.  (not voting)</td>', 'Nice shapes, although I find it is lacking in detail and tonal richness.  (not voting)', '2011-03-30 16:46:08.000000', NULL, 1),
(6367981, 943476, 124256, '<td valign="top">I see it.  I think you echo Weston nicely here, and I love the shot to boot.  Well done!</td>', 'I see it.  I think you echo Weston nicely here, and I love the shot to boot.  Well done!', '2011-03-30 16:46:31.000000', NULL, 1),
(6367982, 943328, 86447, '<td valign="top">Gorgeous!  (not voting)</td>', 'Gorgeous!  (not voting)', '2011-03-30 16:51:21.000000', NULL, 1),
(6367983, 942735, 86447, '<td valign="top">Fabulous!  (not voting)</td>', 'Fabulous!  (not voting)', '2011-03-30 16:54:33.000000', NULL, 1),
(6367984, 943260, 86447, '<td valign="top">Wonderful control!   (not voting)</td>', 'Wonderful control!   (not voting)', '2011-03-30 16:55:09.000000', NULL, 1),
(6368007, 942722, 47470, '<td valign="top">I think it looks very strange how the subject has so much grain and the background is mostly smooth.</td>', 'I think it looks very strange how the subject has so much grain and the background is mostly smooth.', '2011-03-30 17:46:41.000000', NULL, 1),
(6368010, 943625, 100335, '<td valign="top">Could see this front page</td>', 'Could see this front page', '2011-03-30 17:50:16.000000', NULL, 1),
(6368012, 943338, 100335, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2011-03-30 17:52:30.000000', NULL, 1),
(6368018, 942880, 47470, '<td valign="top">The composition is nice, but I would have preferred soft light since that''s what Weston usually used with this type of subject.</td>', 'The composition is nice, but I would have preferred soft light since that''s what Weston usually used with this type of subject.', '2011-03-30 18:01:24.000000', NULL, 1),
(6368019, 943037, 47470, '<td valign="top">I don''t know if it is the light or the BnW or if this lettuce is really wilted and dead.  Either way, Weston had a way of using light to make the subject come alive and look incredibly lustrous, and, for me, you did not do that here.</td>', 'I don''t know if it is the light or the BnW or if this lettuce is really wilted and dead.  Either way, Weston had a way of using light to make the subject come alive and look incredibly lustrous, and, for me, you did not do that here.', '2011-03-30 18:03:37.000000', NULL, 1),
(6368022, 943463, 47470, '<td valign="top">When Weston photographed shells, he selected lighter ones, then lit them so they looked like the light was coming from the shell itself.  Since your shell had blacks and dark greys and the lightest parts are closer to middle/light grey than white, I don''t think you quite matched Weston''s style.</td>', 'When Weston photographed shells, he selected lighter ones, then lit them so they looked like the light was coming from the shell itself.  Since your shell had blacks and dark greys and the lightest parts are closer to middle/light grey than white, I don''t think you quite matched Weston''s style.', '2011-03-30 18:06:59.000000', NULL, 1),
(6368023, 942999, 47470, '<td valign="top">I love that you used a flower on wood, yet didn''t exactly copy Weston''s most famous image of a flower on wood.  This is simple, yet beautiful.  I still would have liked to see more detail and a bit more localized tonality in the wood.</td>', 'I love that you used a flower on wood, yet didn''t exactly copy Weston''s most famous image of a flower on wood.  This is simple, yet beautiful.  I still would have liked to see more detail and a bit more localized tonality in the wood.', '2011-03-30 18:08:39.000000', NULL, 1),
(6368025, 943652, 47470, '<td valign="top">I love the near-symmetry.  I would have liked to see better detail, particularly in some of the shadows.</td>', 'I love the near-symmetry.  I would have liked to see better detail, particularly in some of the shadows.', '2011-03-30 18:09:24.000000', NULL, 1),
(6368030, 943579, 47470, '<td valign="top">Great floor and background wall--they fit very well with the Weston style.  The strange, slightly awkward pose is also typically Weston.  I only would have liked to see a deeper depth of field to capture that texture in the floor and wall.</td>', 'Great floor and background wall--they fit very well with the Weston style.  The strange, slightly awkward pose is also typically Weston.  I only would have liked to see a deeper depth of field to capture that texture in the floor and wall.', '2011-03-30 18:12:01.000000', NULL, 1),
(6368032, 942968, 47470, '<td valign="top">Great tones and texture.</td>', 'Great tones and texture.', '2011-03-30 18:13:28.000000', NULL, 1),
(6368033, 943597, 47470, '<td valign="top">I know tomatoes always seem to look out of focus is photographs due to their strange skin texture, but I think yours is actually OOF since the leaves aren''t as sharp as the stem.  Weston usually used small apertures and long exposures to get a deep depth of field.  The texture in the stem is great though.</td>', 'I know tomatoes always seem to look out of focus is photographs due to their strange skin texture, but I think yours is actually OOF since the leaves aren''t as sharp as the stem.  Weston usually used small apertures and long exposures to get a deep depth of field.  The texture in the stem is great though.', '2011-03-30 18:16:16.000000', NULL, 1),
(6368034, 942650, 61396, '<td valign="top">You got it right. I wonder if you would share the original, as I would love to understand the post processing, but am shy to ask for too much details. (not voting)</td>', 'You got it right. I wonder if you would share the original, as I would love to understand the post processing, but am shy to ask for too much details. (not voting)', '2011-03-30 18:16:22.000000', NULL, 1),
(6368057, 943017, 47470, '<td valign="top">Weston never really used shallow depths of field like this.  He was into texture and tonality, both of which are lost when you open up the aperture.</td>', 'Weston never really used shallow depths of field like this.  He was into texture and tonality, both of which are lost when you open up the aperture.', '2011-03-30 18:29:58.000000', NULL, 1),
