(6374808, 942936, 114225, '<td valign="top">I really like the details and lighting. To me, the Edward Weston style of still life have a background the is completely unobtrusive (e.g. none of those wrinkles showing), but I''m not style expert.</td>', 'I really like the details and lighting. To me, the Edward Weston style of still life have a background the is completely unobtrusive (e.g. none of those wrinkles showing), but I''m not style expert.', '2011-04-05 10:53:19.000000', NULL, 1),
(6374809, 943600, 114225, '<td valign="top">Great job with personifying an everyday object. Mr Weston would be proud.</td>', 'Great job with personifying an everyday object. Mr Weston would be proud.', '2011-04-05 10:53:52.000000', NULL, 1),
(6374811, 943658, 114225, '<td valign="top">I''m not finding that this really fits into the Weston style. Seems very washed out where his style seems to be all about crisp shapes (at least that is how I interpret it).</td>', 'I''m not finding that this really fits into the Weston style. Seems very washed out where his style seems to be all about crisp shapes (at least that is how I interpret it).', '2011-04-05 10:54:46.000000', NULL, 1),
(6374813, 943488, 114225, '<td valign="top">To me, Weston''s photos are all very clean. This has a lot of background clutter distracting from the main subject.</td>', 'To me, Weston''s photos are all very clean. This has a lot of background clutter distracting from the main subject.', '2011-04-05 11:01:02.000000', NULL, 1),
(6374814, 943484, 67152, '<td valign="top">a great idea and very close to succeeding but the lighting streams are harsh and result in blown out portions</td>', 'a great idea and very close to succeeding but the lighting streams are harsh and result in blown out portions', '2011-04-05 11:01:03.000000', NULL, 1),
(6374817, 943260, 114225, '<td valign="top">Great choice of lighting to really bring out those intricate details.</td>', 'Great choice of lighting to really bring out those intricate details.', '2011-04-05 11:01:34.000000', NULL, 1),
(6374818, 943643, 114225, '<td valign="top">Very good use of clean shapes and lines. That''s what I feel is the heart of the Weston style.</td>', 'Very good use of clean shapes and lines. That''s what I feel is the heart of the Weston style.', '2011-04-05 11:01:56.000000', NULL, 1),
(6374822, 943604, 114225, '<td valign="top">Nice subject. I feel the lighting is very un-Weston like. Looks like a direct flash was used which is creating some harsh shadows and reflections. I believe Weston mostly went for natural-style light on his still lifes.</td>', 'Nice subject. I feel the lighting is very un-Weston like. Looks like a direct flash was used which is creating some harsh shadows and reflections. I believe Weston mostly went for natural-style light on his still lifes.', '2011-04-05 11:03:26.000000', NULL, 1),
(6374824, 942777, 114225, '<td valign="top">That''s pretty cool capturing the water droplet in there. I like the lines and composition.</td>', 'That''s pretty cool capturing the water droplet in there. I like the lines and composition.', '2011-04-05 11:04:06.000000', NULL, 1),
(6374828, 943471, 114225, '<td valign="top">You chose very good lighting for this subject: accentuating the lines without causing sharp shadows.</td>', 'You chose very good lighting for this subject: accentuating the lines without causing sharp shadows.', '2011-04-05 11:05:40.000000', NULL, 1),
(6374841, 943614, 114225, '<td valign="top">I really enjoy this photo. The curves, eye leading features, and mystery make this very cool.</td>', 'I really enjoy this photo. The curves, eye leading features, and mystery make this very cool.', '2011-04-05 11:15:50.000000', NULL, 1),
(6374842, 943329, 86218, '<td valign="top">This works perfectly. Great shot</td>', 'This works perfectly. Great shot', '2011-04-05 11:16:18.000000', NULL, 1),
(6374844, 943365, 86218, '<td valign="top">The lighting and processing on this image is in another class. I love this and the form chosen here beyond the rational logical thing for a pepper. Makes it work and upping this from 7 - 8</td>', 'The lighting and processing on this image is in another class. I love this and the form chosen here beyond the rational logical thing for a pepper. Makes it work and upping this from 7 - 8', '2011-04-05 11:17:22.000000', NULL, 1),
(6374847, 943466, 47249, '<td valign="top">Perhaps not a perfect Weston style, but I love this one too much. So just adjusted the 6 I''ve given up to 10.</td>', 'Perhaps not a perfect Weston style, but I love this one too much. So just adjusted the 6 I''ve given up to 10.', '2011-04-05 11:24:29.000000', NULL, 1),
(6374848, 943238, 47249, '<td valign="top">Simply wonderful!</td>', 'Simply wonderful!', '2011-04-05 11:25:42.000000', NULL, 1),
(6374857, 943497, 116631, '<td valign="top">one of my favorites!</td>', 'one of my favorites!', '2011-04-05 11:43:19.000000', NULL, 1),
(6374906, 943476, 118154, '<td valign="top">Just adore that face.Top four for me.</td>', 'Just adore that face.Top four for me.', '2011-04-05 12:17:49.000000', NULL, 1),
(6374965, 943260, 129091, '<td valign="top">Nice texture and light!</td>', 'Nice texture and light!', '2011-04-05 13:22:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6374966, 943471, 129091, '<td valign="top">Nice idea!</td>', 'Nice idea!', '2011-04-05 13:23:24.000000', NULL, 1),
(6375051, 942776, 69034, '<td valign="top">This is one of my faves from the challenge.  Excellent way to go with the challenge but not follow expected norms.  This is exactly the way Weston did photography.  Make people see a normal item, then flip it outside of expectation.</td>', 'This is one of my faves from the challenge.  Excellent way to go with the challenge but not follow expected norms.  This is exactly the way Weston did photography.  Make people see a normal item, then flip it outside of expectation.', '2011-04-05 14:33:54.000000', NULL, 1),
(6375092, 943668, 54446, '<td valign="top">Good match to Weston''s style.</td>', 'Good match to Weston''s style.', '2011-04-05 15:11:17.000000', NULL, 1),
(6375094, 943365, 54446, '<td valign="top">Really good light and form and texture.  I think you did a fine job with Weston''s style.</td>', 'Really good light and form and texture.  I think you did a fine job with Weston''s style.', '2011-04-05 15:12:05.000000', NULL, 1),
(6375096, 942561, 54446, '<td valign="top">One of my favorites in this challenge.  Good form, light, texture, shadow.</td>', 'One of my favorites in this challenge.  Good form, light, texture, shadow.', '2011-04-05 15:12:59.000000', NULL, 1),
(6375100, 942811, 54446, '<td valign="top">Very cool artichoke.  Amazing detail and exposure. (Better than Weston''s stuff.)</td>', 'Very cool artichoke.  Amazing detail and exposure. (Better than Weston''s stuff.)', '2011-04-05 15:13:42.000000', NULL, 1),
(6375103, 943182, 54446, '<td valign="top">Fine job.  Looks "Weston-like" to me.</td>', 'Fine job.  Looks "Weston-like" to me.', '2011-04-05 15:14:23.000000', NULL, 1),
(6375105, 942718, 54446, '<td valign="top">I like the mushroom flute texture very much.  The bg... not as much.</td>', 'I like the mushroom flute texture very much.  The bg... not as much.', '2011-04-05 15:15:15.000000', NULL, 1),
(6375108, 943497, 54446, '<td valign="top">It''s a great b&amp;w.  More like AA, than Weston.  I enjoyed viewing this, especially the shadows and view into the bottom of the water pools.</td>', 'It''s a great b&w.  More like AA, than Weston.  I enjoyed viewing this, especially the shadows and view into the bottom of the water pools.', '2011-04-05 15:16:33.000000', NULL, 1),
(6375110, 943335, 54446, '<td valign="top">Very natural looking nude in a nature setting.  Well done.</td>', 'Very natural looking nude in a nature setting.  Well done.', '2011-04-05 15:17:42.000000', NULL, 1),
(6375126, 942996, 124256, '<td valign="top">Nice shot.  I really think Weston would have shot the underside, from the top, just the stem, or tightly cropped on the side unless he found a specimen with a very unusual shape.  Aside from that, I think the focus, contrast, balance of light and dark, and framing all strongly suggest Weston.</td>', 'Nice shot.  I really think Weston would have shot the underside, from the top, just the stem, or tightly cropped on the side unless he found a specimen with a very unusual shape.  Aside from that, I think the focus, contrast, balance of light and dark, and framing all strongly suggest Weston.', '2011-04-05 15:31:39.000000', NULL, 1),
(6375129, 943407, 124256, '<td valign="top">Awesome.  Weston''s shots like this make me think of children''s books where you are supposed to lift a flap to see what''s underneath.  I''m not sure what I mean by that, but I think you have captured it here.  I love the reflection in the window, and I''m not sure how Westony it is, so I''ll leave it alone.  Nice shot.</td>', 'Awesome.  Weston''s shots like this make me think of children''s books where you are supposed to lift a flap to see what''s underneath.  I''m not sure what I mean by that, but I think you have captured it here.  I love the reflection in the window, and I''m not sure how Westony it is, so I''ll leave it alone.  Nice shot.', '2011-04-05 15:34:08.000000', NULL, 1),
(6375132, 943497, 124256, '<td valign="top">Fascinating.  Somehow the pool looks very swollen to me, like a bubble.  The strong shape I think is very Westonesque in a pleasing way.  Focus, contrast, balance of dark and light, all are very Westony.  Well done!</td>', 'Fascinating.  Somehow the pool looks very swollen to me, like a bubble.  The strong shape I think is very Westonesque in a pleasing way.  Focus, contrast, balance of dark and light, all are very Westony.  Well done!', '2011-04-05 15:36:12.000000', NULL, 1),
(6375137, 943627, 124256, '<td valign="top">This doesn''t seem a lot like any Weston shot I can think of, but I wouldn''t be surprised to find one like this.  I think you succeeded.</td>', 'This doesn''t seem a lot like any Weston shot I can think of, but I wouldn''t be surprised to find one like this.  I think you succeeded.', '2011-04-05 15:38:09.000000', NULL, 1),
(6375139, 943636, 124256, '<td valign="top">Okay, I think I see the Weston.  Nice shot.</td>', 'Okay, I think I see the Weston.  Nice shot.', '2011-04-05 15:38:29.000000', NULL, 1),
(6375140, 943591, 124256, '<td valign="top">The more I look at this the more it works for me as a Weston.  Well done!</td>', 'The more I look at this the more it works for me as a Weston.  Well done!', '2011-04-05 15:38:57.000000', NULL, 1),
(6375142, 943639, 106484, '<td valign="top">Love the sky.</td>', 'Love the sky.', '2011-04-05 15:40:11.000000', NULL, 1),
(6375143, 943087, 124256, '<td valign="top">To me this does not look like any Weston photograph.  It does, however, seems to capture some kind of Westoniness I can''t substantiate.  It seems like a shot Weston could have taken.  Nice.</td>', 'To me this does not look like any Weston photograph.  It does, however, seems to capture some kind of Westoniness I can''t substantiate.  It seems like a shot Weston could have taken.  Nice.', '2011-04-05 15:41:01.000000', NULL, 1),
(6375144, 943463, 124256, '<td valign="top">Nice recreation of Weston''s shot.</td>', 'Nice recreation of Weston''s shot.', '2011-04-05 15:42:09.000000', NULL, 1),
(6375147, 942658, 106484, '<td valign="top">Nice, but I would have preferred a deeper crop as there''s a lot of black space. Also, because it''s an advanced editing challenge you could have removed the wrinkles and imperfections in the skin.</td>', 'Nice, but I would have preferred a deeper crop as there''s a lot of black space. Also, because it''s an advanced editing challenge you could have removed the wrinkles and imperfections in the skin.', '2011-04-05 15:43:23.000000', NULL, 1),
(6375148, 943579, 124256, '<td valign="top">Truncated nude with other form also with curves that interact with/mirror other curves.  Okay, I think I get it.  I wish there were darker darks, or just more dark areas for what I think is a more Westony balance.</td>', 'Truncated nude with other form also with curves that interact with/mirror other curves.  Okay, I think I get it.  I wish there were darker darks, or just more dark areas for what I think is a more Westony balance.', '2011-04-05 15:44:13.000000', NULL, 1),
(6375150, 943228, 106484, '<td valign="top">Personally I would have preferred to see the waves and clouds in focus, but I suppose it could take away from the subject.</td>', 'Personally I would have preferred to see the waves and clouds in focus, but I suppose it could take away from the subject.', '2011-04-05 15:46:03.000000', NULL, 1),
(6375151, 943221, 124256, '<td valign="top">Nice.  I might even like it more if the door was truncated like Weston''s church door photo.  I really like the balance between light and dark -- seems very Westony.</td>', 'Nice.  I might even like it more if the door was truncated like Weston''s church door photo.  I really like the balance between light and dark -- seems very Westony.', '2011-04-05 15:46:11.000000', NULL, 1),
(6375153, 942811, 106484, '<td valign="top">Nice, but I would have preferred a deeper crop as there''s a lot of black space. Also, because it''s an advanced editing challenge you could have</td>', 'Nice, but I would have preferred a deeper crop as there''s a lot of black space. Also, because it''s an advanced editing challenge you could have', '2011-04-05 15:47:20.000000', NULL, 1),
(6375154, 942393, 124256, '<td valign="top">Something about the glove I think detracts from the timelessness of Weston''s photos.  Ignoring that, I think you have captured the spirit of his nudes and I love it.</td>', 'Something about the glove I think detracts from the timelessness of Weston''s photos.  Ignoring that, I think you have captured the spirit of his nudes and I love it.', '2011-04-05 15:47:48.000000', NULL, 1),
(6375155, 943365, 124256, '<td valign="top">Yeah, I see the Weston in this shot.  I love the melted face/curved body shape of the pepper.</td>', 'Yeah, I see the Weston in this shot.  I love the melted face/curved body shape of the pepper.', '2011-04-05 15:47:59.000000', NULL, 1),
(6375156, 943604, 106484, '<td valign="top">I little under-exposed for me, and it might have worked better with a tighter crop.</td>', 'I little under-exposed for me, and it might have worked better with a tighter crop.', '2011-04-05 15:48:14.000000', NULL, 1),
(6375157, 943471, 124256, '<td valign="top">I think I would have offset the cropping, but I think this is a stong Weston entry.</td>', 'I think I would have offset the cropping, but I think this is a stong Weston entry.', '2011-04-05 15:48:44.000000', NULL, 1),
(6375160, 943658, 106484, '<td valign="top">Needs a contrast boost in my opinion, and maybe a more interesting angle.</td>', 'Needs a contrast boost in my opinion, and maybe a more interesting angle.', '2011-04-05 15:49:34.000000', NULL, 1),
(6375161, 942545, 106484, '<td valign="top">I like!!</td>', 'I like!!', '2011-04-05 15:51:01.000000', NULL, 1),
(6375162, 943663, 124256, '<td valign="top">In the spirit of Weston as I understand what I have seen of his work, I wish the shot was less dramatic (I''m thinking particularly of the shaded are on the left).  I also wish the highlights were lighter, or at least that there were more brightly lit areas.  And not all of your specimen is in focus, I think Weston definitely would have taken care of that.  That said I think your specimen, contrast, attention to form, all make for a nice Westony shot.</td>', 'In the spirit of Weston as I understand what I have seen of his work, I wish the shot was less dramatic (I''m thinking particularly of the shaded are on the left).  I also wish the highlights were lighter, or at least that there were more brightly lit areas.  And not all of your specimen is in focus, I think Weston definitely would have taken care of that.  That said I think your specimen, contrast, attention to form, all make for a nice Westony shot.', '2011-04-05 15:52:09.000000', NULL, 1),
(6375164, 943310, 124256, '<td valign="top">Nice specimen.  I think the biggest area lacking is lighting.  Based on my read, Weston would have had more softer lighting for greater contrast between light and dark, and more balance between light and dark.</td>', 'Nice specimen.  I think the biggest area lacking is lighting.  Based on my read, Weston would have had more softer lighting for greater contrast between light and dark, and more balance between light and dark.', '2011-04-05 15:53:41.000000', NULL, 1),
(6375165, 943408, 124256, '<td valign="top">I am going to say I think this does echo Weston, just not in an obvious way.  I think it''s harder to quantify his style in landscapes.  I like it.</td>', 'I am going to say I think this does echo Weston, just not in an obvious way.  I think it''s harder to quantify his style in landscapes.  I like it.', '2011-04-05 15:53:50.000000', NULL, 1),
(6375166, 943592, 106484, '<td valign="top">It''s very busy. I''m wondering if it might have worked with a shallower depth of field.</td>', 'It''s very busy. I''m wondering if it might have worked with a shallower depth of field.', '2011-04-05 15:54:31.000000', NULL, 1),
(6375168, 943616, 106484, '<td valign="top">I like that I can''t quite make out what it is...interesting shot.</td>', 'I like that I can''t quite make out what it is...interesting shot.', '2011-04-05 15:56:23.000000', NULL, 1),
(6375172, 943428, 106484, '<td valign="top">Haha....excellent. Hope this does well.</td>', 'Haha....excellent. Hope this does well.', '2011-04-05 15:58:38.000000', NULL, 1),
(6375176, 943365, 106484, '<td valign="top">My favourite pepper shot so far, great texture and lighting. Shame about the imperfection though, given it''s an advanced editing challenge you could have cloned it out perhaps.</td>', 'My favourite pepper shot so far, great texture and lighting. Shame about the imperfection though, given it''s an advanced editing challenge you could have cloned it out perhaps.', '2011-04-05 16:02:22.000000', NULL, 1),
(6375201, 943181, 25522, '<td valign="top">bbv</td>', 'bbv', '2011-04-05 16:35:34.000000', NULL, 1),
(6375208, 942369, 11769, '<td valign="top">Nice expression, Well done. Sensuous and emotive.</td>', 'Nice expression, Well done. Sensuous and emotive.', '2011-04-05 16:50:31.000000', NULL, 1),
(6375210, 942650, 11769, '<td valign="top">The light and profoundly odd placement of the foot along with processing make this one of my favorites.</td>', 'The light and profoundly odd placement of the foot along with processing make this one of my favorites.', '2011-04-05 16:50:43.000000', NULL, 1),
(6375211, 943598, 11769, '<td valign="top">How appropriate, weather worn and slowly disintegrating. HA HA!</td>', 'How appropriate, weather worn and slowly disintegrating. HA HA!', '2011-04-05 16:50:54.000000', NULL, 1),
(6375212, 943616, 11769, '<td valign="top">Strangely reminiscent of Pollock.</td>', 'Strangely reminiscent of Pollock.', '2011-04-05 16:51:02.000000', NULL, 1),
(6375213, 942704, 11769, '<td valign="top">Sky dramatic.</td>', 'Sky dramatic.', '2011-04-05 16:51:06.000000', NULL, 1),
(6375214, 943423, 11769, '<td valign="top">Love the humor in this. A very important appendage.</td>', 'Love the humor in this. A very important appendage.', '2011-04-05 16:51:27.000000', NULL, 1),
(6375215, 943228, 11769, '<td valign="top">From foreground to horizon a sense of desolation.</td>', 'From foreground to horizon a sense of desolation.', '2011-04-05 16:51:34.000000', NULL, 1),
(6375216, 943518, 11769, '<td valign="top">In it''s simplicity I find beauty. Love the shadow.</td>', 'In it''s simplicity I find beauty. Love the shadow.', '2011-04-05 16:51:44.000000', NULL, 1),
(6375217, 942968, 11769, '<td valign="top">Love the vine</td>', 'Love the vine', '2011-04-05 16:52:07.000000', NULL, 1),
(6375218, 942559, 11769, '<td valign="top">Great wall, very detailed.</td>', 'Great wall, very detailed.', '2011-04-05 16:52:16.000000', NULL, 1),
(6375219, 942597, 11769, '<td valign="top">That scares me Edward.</td>', 'That scares me Edward.', '2011-04-05 16:52:23.000000', NULL, 1),
(6375220, 943087, 11769, '<td valign="top">Beautiful tones and composition,</td>', 'Beautiful tones and composition,', '2011-04-05 16:52:30.000000', NULL, 1),
(6375221, 943614, 11769, '<td valign="top">Nice composition. This is nice.</td>', 'Nice composition. This is nice.', '2011-04-05 16:52:36.000000', NULL, 1),
(6375222, 943315, 11769, '<td valign="top">Found a new home.</td>', 'Found a new home.', '2011-04-05 16:52:42.000000', NULL, 1),
(6375223, 943238, 11769, '<td valign="top">Serene.</td>', 'Serene.', '2011-04-05 16:52:50.000000', NULL, 1),
(6375224, 943413, 11769, '<td valign="top">Wonderful street action.</td>', 'Wonderful street action.', '2011-04-05 16:52:54.000000', NULL, 1),
(6375225, 943284, 11769, '<td valign="top">Excellent portrait</td>', 'Excellent portrait', '2011-04-05 16:53:01.000000', NULL, 1),
(6375229, 943627, 11769, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2011-04-05 16:56:52.000000', NULL, 1),
(6375300, 943282, 120171, '<td valign="top">Simply brilliant.</td>', 'Simply brilliant.', '2011-04-05 18:37:33.000000', NULL, 1),
(6375302, 943328, 120171, '<td valign="top">Simplicity at its best.</td>', 'Simplicity at its best.', '2011-04-05 18:40:29.000000', NULL, 1),
(6375409, 943639, 124982, '<td valign="top">Really like this composition...particularly the moody, dark feel to it.</td>', 'Really like this composition...particularly the moody, dark feel to it.', '2011-04-05 21:04:20.000000', NULL, 1),
(6375412, 942661, 124982, '<td valign="top">Very simple, but elegant. Think the negative space makes the figure seem so lonely and filled with despair. Not sure if that is what you were going for, but it works for me!</td>', 'Very simple, but elegant. Think the negative space makes the figure seem so lonely and filled with despair. Not sure if that is what you were going for, but it works for me!', '2011-04-05 21:05:33.000000', NULL, 1),
(6375485, 943328, 16241, '<td valign="top">should ribbon, best veg on show :)</td>', 'should ribbon, best veg on show :)', '2011-04-05 22:45:45.000000', NULL, 1),
(6375487, 943482, 16241, '<td valign="top">lol - 8</td>', 'lol - 8', '2011-04-05 22:46:26.000000', NULL, 1),
(6375537, 943290, 50695, '<td valign="top">oddly enough, I feel too biased to keep bumping up this photo, even though I can''t really say that I know you or the subject. It''s to your credit that I feel like I know both. The photograph is sKul(p)tur ... marble... you have evoked the cold eye of Weston perhaps better than anyone else. Like Weston, you have chosen not to "freeze a moment in time" but rather to turn your subject into stone... of course you still deal in eternity.</td>', 'oddly enough, I feel too biased to keep bumping up this photo, even though I can''t really say that I know you or the subject. It''s to your credit that I feel like I know both. The photograph is sKul(p)tur ... marble... you have evoked the cold eye of Weston perhaps better than anyone else. Like Weston, you have chosen not to "freeze a moment in time" but rather to turn your subject into stone... of course you still deal in eternity.', '2011-04-05 23:11:39.000000', NULL, 1),
(6375538, 942748, 50695, '<td valign="top">good dark tones</td>', 'good dark tones', '2011-04-05 23:11:54.000000', NULL, 1),
(6375540, 942968, 50695, '<td valign="top">gorgeous kinetic picture</td>', 'gorgeous kinetic picture', '2011-04-05 23:12:41.000000', NULL, 1),
(6375553, 943428, 50695, '<td valign="top">Hilarious.</td>', 'Hilarious.', '2011-04-05 23:17:47.000000', NULL, 1),
