INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6376172, 943282, 117474, '<td valign="top">I was going to say it was the lowest ribbon score I ever saw, but then realised that you came second rather than third... so second lowest ribbon score I''ve ever seen :-)<br/>I like the lighting in this a lot. Not Weston-esque, perhaps, but still nice.<br/> <br/>I''ve come to realise I should try commenting in French on your shots (hoping you''ll forgive the lack of accenting, poor grammar, woeful spelling and embarrassing attempts at the language... haven''t spoken/written it in 7 years or more and wasn''t good at it when I did either)...<br/>Il est tres difficule de trouver les fruites de forme irregulere dans les grandes villes. Je n''en pouvais pas trouver [desole! c''est difficule!]... mais je suis regarde un navel qui ressemblait un "thingie" mais... le "thingie"... um... ne faudrait etre appreciee...<br/> <br/>I think I may stop commenting in French if that''s OK :-)<br/></td>', 'I was going to say it was the lowest ribbon score I ever saw, but then realised that you came second rather than third... so second lowest ribbon score I''ve ever seen :-)I like the lighting in this a lot. Not Weston-esque, perhaps, but still nice. I''ve come to realise I should try commenting in French on your shots (hoping you''ll forgive the lack of accenting, poor grammar, woeful spelling and embarrassing attempts at the language... haven''t spoken/written it in 7 years or more and wasn''t good at it when I did either)...Il est tres difficule de trouver les fruites de forme irregulere dans les grandes villes. Je n''en pouvais pas trouver [desole! c''est difficule!]... mais je suis regarde un navel qui ressemblait un "thingie" mais... le "thingie"... um... ne faudrait etre appreciee... I think I may stop commenting in French if that''s OK :-)', '2011-04-06 06:19:55.000000', NULL, 0),
(6376179, 943199, 64086, '<td valign="top">Beautiful photo, with lovely light and texture.<br/><br/><i>Message edited by author 2011-04-06 05:51:12.</i></td>', 'Beautiful photo, with lovely light and texture.', '2011-04-06 06:50:46.000000', '2011-04-06 06:51:12.000000', 0),
